import java.util.*;

class Solution {
    public int subarraysWithKDistinct(int[] nums, int k) {
        return atMost(nums, k) - atMost(nums, k - 1);
    }

    // number of subarrays with at most k distinct values
    private int atMost(int[] nums, int k) {
        if (k <= 0) return 0;
        Map<Integer, Integer> cnt = new HashMap<>(); // value -> count inside the window
        int left = 0, kinds = 0, total = 0;
        for (int right = 0; right < nums.length; right++) {
            if (cnt.merge(nums[right], 1, Integer::sum) == 1) kinds++;
            while (kinds > k) {
                if (cnt.merge(nums[left], -1, Integer::sum) == 0) kinds--;
                left++;
            }
            total += right - left + 1; // all runs ending at right with at most k kinds
        }
        return total;
    }
}

